  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_persona_documento` (`tipo_documento`,`numero_documento`),
  KEY `ix_persona_nombre` (`apellidos`,`nombres`),
  CONSTRAINT `ck_persona_sexo` CHECK (((`sexo` is null) or (`sexo` in (_utf8mb4'M',_utf8mb4'F')))),
